    55  int MqttSocket_TlsSocketReceive(WOLFSSL* ssl, char *buf, int sz,
    56      void *ptr)
    57  {
    58      int rc;
    59      MqttClient *client = (MqttClient*)ptr;
    60      (void)ssl; /* Not used */
    61
    62      rc = client->net->read(client->net->context, (byte*)buf, sz,
    63          client->tls.timeout_ms);
    64
    65      /* save network read response */
    66      client->tls.sockRcRead = rc;
    67
    68      if (rc == 0 || rc == MQTT_CODE_ERROR_TIMEOUT || rc == MQTT_CODE_STDIN_WAKE
    69                                                   || rc == MQTT_CODE_CONTINUE) {
    70          rc = WOLFSSL_CBIO_ERR_WANT_READ;
    71      }
    72      else if (rc < 0) {
    73          rc = WOLFSSL_CBIO_ERR_GENERAL;
    74      }
    75      return rc;
    76  }
