   101  int MqttSocket_Init(MqttClient *client, MqttNet *net)
   102  {
   103      int rc = MQTT_CODE_ERROR_BAD_ARG;
   104      if (client) {
   105          client->net = net;
   106          MqttClient_Flags(client, (MQTT_CLIENT_FLAG_IS_CONNECTED |
   107              MQTT_CLIENT_FLAG_IS_TLS), 0);;
   108      #ifdef ENABLE_MQTT_TLS
   109          client->tls.ctx = NULL;
   110          client->tls.ssl = NULL;
   111          client->tls.timeout_ms = client->cmd_timeout_ms;
   112      #endif
   113
   114          /* Validate callbacks are not null! */
   115          if (net && net->connect && net->read && net->write && net->disconnect) {
   116              rc = MQTT_CODE_SUCCESS;
   117          }
   118      }
   119      return rc;
   120  }
