   224  static int MqttSocket_ReadDo(MqttClient *client, byte* buf, int buf_len,
   225      int timeout_ms)
   226  {
   227      int rc;
   228
   229  #ifdef ENABLE_MQTT_TLS
   230      if (MqttClient_Flags(client,0,0) & MQTT_CLIENT_FLAG_IS_TLS) {
   231          client->tls.timeout_ms = timeout_ms;
   232          client->tls.sockRcRead = 0; /* init value */
   233          rc = wolfSSL_read(client->tls.ssl, (char*)buf, buf_len);
   234          if (rc < 0) {
   235              int error = wolfSSL_get_error(client->tls.ssl, 0);
   236          #ifdef WOLFMQTT_DEBUG_SOCKET
   237              if (error != WOLFSSL_ERROR_WANT_READ
   238              #ifdef WOLFSSL_ASYNC_CRYPT
   239                  && error != WC_PENDING_E
   240              #endif
   241              ) {
   242                  PRINTF("MqttSocket_ReadDo: SSL Error=%d (rc %d, sockrc %d)",
   243                      error, rc, client->tls.sockRcRead);
   244              }
   245          #endif
   246
   247              /* return code from net callback */
   248              rc = client->tls.sockRcRead;
   249          #ifdef WOLFSSL_ASYNC_CRYPT
   250              if (error == WC_PENDING_E) {
   251                  rc = MQTT_CODE_CONTINUE;
   252              }
   253              else
   254          #endif
   255              /* used with compatibility layer to communicate peer close */
   256              if (error == WOLFSSL_ERROR_ZERO_RETURN) {
   257                  rc = MQTT_CODE_ERROR_NETWORK;
   258              }
   259          }
   260      }
